from warehouse_fleet import FleetSimulator, GridMap, Robot, Task
from warehouse_fleet.pathfinding import shortest_path

random.seed(1234)
violations = 0
for trial in range(400):
    w, h = random.randint(1, 6), random.randint(1, 4)
    cells = [(x, y) for x in range(w) for y in range(h)]
    obstacles = frozenset(random.sample(cells, k=random.randint(0, max(0, len(cells)-2))))
    grid = GridMap(w, h, obstacles)
    free = [c for c in cells if grid.traversable(c)]
    if len(free) < 2:
        continue
    n_robots = random.randint(1, min(4, len(free)))
    starts = random.sample(free, n_robots)
    robots = [Robot(f"R{i}", p) for i, p in enumerate(starts)]
    tasks = []
    for i, robot in enumerate(robots):
        if random.random() < 0.6:
            goals = [c for c in free if c != robot.position]
            if not goals:
                continue
            drop = random.choice(goals)
            try:
                route = shortest_path(grid, robot.position, drop)
            except ValueError:
                continue
            tid = f"T{i}"
            tasks.append(Task(tid, robot.position, drop, assigned_robot=robot.robot_id, picked_up=True))
            robot.task_id = tid
            robot.route = route
    sim = FleetSimulator(grid, robots, tasks)
    prev = {r.robot_id: r.position for r in robots}
    for tick in range(30):
        ev = sim.step()
        cur = {rid: tuple(c) for rid, c in ev["robots"].items()}
        # no overlaps
        if len(set(cur.values())) != len(cur):
            print("OVERLAP trial", trial, cur); violations += 1; break
        # no swaps, max one cell
        ids = list(cur)
        for a in ids:
            d = abs(cur[a][0]-prev[a][0]) + abs(cur[a][1]-prev[a][1])
            if d > 1:
                print("JUMP", trial, a, prev[a], cur[a]); violations += 1
        for i, a in enumerate(ids):
            for b in ids[i+1:]:
                if cur[a] == prev[b] and cur[b] == prev[a] and cur[a] != prev[a]:
                    print("SWAP", trial, a, b); violations += 1
        # moved list exact
        moved = {rid for rid in ids if cur[rid] != prev[rid]}
        if set(ev["moved"]) != moved:
            print("MOVED MISMATCH", trial, ev["moved"], moved); violations += 1
        # no obstacle entry
        for rid, pos in cur.items():
            if not grid.traversable(pos):
                print("OBSTACLE", trial, rid, pos); violations += 1
        prev = cur
    if violations > 3:
        break
print("trials done, violations:", violations)
